code.content:
/* taille par défaut du navigateur : 16px */
.card { font-size: 1.25rem; }
.card p {
  font-size: 1.5em;
  padding: 1rem;
}

.hero {
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}
.card { flex: 1 1 15rem; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1rem;
}

.card { position: relative; }
.card .badge {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
}

:root { --bg: #fff; --text: #1a1a1a; }
@media (prefers-color-scheme: dark) {
  :root { --bg: #121212; --text: #eee; }
}
body {
  background: var(--bg);
  color: var(--text);
}
